import{_ as e,c as a,o as d,ae as r}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Set Shipping Method","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-cart-set-shipping-method","title":"Set Shipping Method","description":"Save the chosen shipping method on the draft cart.","query":"mutation SetShipping($input: setShippingMethodAdminCartInput!) {\\n  setShippingMethodAdminCart(input: $input) {\\n    adminCart {\\n      itemsCount\\n      grandTotal\\n      formattedGrandTotal\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/carts/314\\",\\n    \\"cartId\\": 314,\\n    \\"shippingMethod\\": \\"flatrate_flatrate\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"setShippingMethodAdminCart\\": {\\n      \\"adminCart\\": {\\n        \\"itemsCount\\": 1,\\n        \\"grandTotal\\": 100,\\n        \\"formattedGrandTotal\\": \\"$100.00\\",\\n        \\"success\\": true,\\n        \\"message\\": \\"Shipping method saved.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/carts/set-shipping-method.md","filePath":"api/graphql-api/admin/sales/carts/set-shipping-method.md"}'),i={name:"api/graphql-api/admin/sales/carts/set-shipping-method.md"};function o(n,t,s,c,h,p){return d(),a("div",null,t[0]||(t[0]=[r('<h1 id="set-shipping-method" tabindex="-1">Set Shipping Method <a class="header-anchor" href="#set-shipping-method" aria-label="Permalink to &quot;Set Shipping Method&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Select cart fields, not <code>id</code></p><p>This mutation returns the updated cart — select <code>itemsCount</code>, <code>grandTotal</code>, <code>formattedGrandTotal</code>, <code>success</code>, <code>message</code>, etc. Do <strong>not</strong> select <code>id</code> (or <code>_id</code>): this is an action result with no addressable record, so the auto-generated IRI field is <code>null</code> and selecting it errors out the whole payload.</p></div><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example uses an illustrative cart id. Admin cart endpoints only operate on <strong>draft carts</strong> (<code>is_active=0</code>) — storefront carts are rejected by the admin cart guard. Create a draft cart first with the <a href="./../../customers/create-draft-cart.html"><code>createAdminDraftCart</code></a> mutation and use the returned <code>cartId</code>.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>setShippingMethodAdminCart(input)</code></td><td>Mutation</td><td>Save the chosen shipping method on the draft cart</td></tr></tbody></table><p><code>input.id</code> is the resource IRI; <code>cartId</code> is the integer id (both are accepted because GraphQL inputs use <code>id</code> reserved as the resource IRI).</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cause</th><th>Notes</th></tr></thead><tbody><tr><td>409 — addresses missing</td><td>Save addresses first via <code>saveAddressAdminCart</code></td></tr><tr><td>400 — shippingMethod missing</td><td>Input must include <code>shippingMethod</code></td></tr><tr><td>403 — active storefront cart</td><td>Only draft carts can be modified</td></tr><tr><td>Unauthenticated</td><td>Missing admin Bearer token</td></tr></tbody></table>',8)]))}const u=e(i,[["render",o]]);export{m as __pageData,u as default};
